using Essco.Application.Inventory;using Essco.Application.Security;using Essco.Domain.Inventory;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;namespace Essco.Web.Pages.Inventory;[Authorize(Policy=Permissions.Warehouse)]public sealed class GroupsModel(InventoryService service):PageModel{public PhysicalInventory Inventory{get;private set;}=null!;public IReadOnlyCollection<InventoryGroup>Items{get;private set;}=[];[BindProperty]public InputModel Input{get;set;}=new();[TempData]public string?StatusMessage{get;set;}public async Task<IActionResult>OnGetAsync(int id,CancellationToken t)=>await Load(id,t)?Page():NotFound();public async Task<IActionResult>OnPostSaveAsync(int id,CancellationToken t){var r=await service.SaveGroupAsync(new(id,Input.Code,Input.Responsible,Input.Companion,Input.SupplierCode,Input.SupplierName),t);if(r.Succeeded){StatusMessage="Grupo agregado.";return RedirectToPage(new{id});}foreach(var e in r.Errors)ModelState.AddModelError("",e);await Load(id,t);return Page();}public async Task<IActionResult>OnPostDeleteAsync(int id,string code,string supplier,CancellationToken t){StatusMessage=await service.DeleteGroupAsync(id,code,supplier,t)?"Asignación eliminada.":"No se eliminó: puede contener conteos o el inventario está cerrado.";return RedirectToPage(new{id});}private async Task<bool>Load(int id,CancellationToken t){var x=await service.GetAsync(id,t);if(x is null)return false;Inventory=x;Items=await service.ListGroupsAsync(id,t);return true;}public sealed class InputModel{public string Code{get;set;}="";public string Responsible{get;set;}="";public string Companion{get;set;}="";public string SupplierCode{get;set;}="";public string SupplierName{get;set;}="";}}
